<?php $colleges=$pdo->query("SELECT id,name FROM colleges ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);?><section class="wrap section narrow"><span class="eyebrow">ADMISSION ENQUIRY</span><h1>Start your admission journey</h1><?php if(!logged_in()):?><p>Please <a href="<?=url('login')?>">login</a> or <a href="<?=url('register')?>">register</a> before submitting an enquiry.</p><?php else:?><form class="form panel" method="post" action="<?=BASE_URL?>/actions/admission.php"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Institution</label><select name="college_id"><option value="">Not selected</option><?php foreach($colleges as $c):?><option value="<?=$c['id']?>" <?=((int)($_GET['college_id']??0)==$c['id'])?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select><label>Course / Programme</label><input name="course" required placeholder="e.g. B.Tech Computer Science"><label>Study mode</label><select name="mode"><option>Regular</option><option>Distance</option></select><label>Academic session</label><input name="session" placeholder="2026-27"><label>Notes</label><textarea name="notes"></textarea><button class="btn btn-primary full">Submit enquiry</button></form><?php endif;?></section>